class Solution {
public:
    int titleToNumber(string s) {
        //for String ABZ and its corresponding number n:
        //n = (A+1) * 26^2 + (B+1) * 26^1 + (Z+1) * 26^0
        int n=s.size();
        int j=n-1;
        int ans=0;
        for(int i=0;i<n;i++)
        {
            ans+=(s[i]-'A'+1)*pow(26,j);
            j-=1;
        }
        return ans;
    }
};

